from bisect import bisect_left
from hashlib import sha256

def h(texto):
    return int.from_bytes(sha256(texto.encode()).digest()[:8], 'big')

def dono(chave, membros):
    anel = sorted((h(f'{m}:{i}'), m) for m in membros for i in range(32))
    if not anel:
        raise ValueError('Anel vazio')
    posicoes = [p for p, _ in anel]
    return anel[bisect_left(posicoes, h(chave)) % len(anel)][1]

print(dono('cliente:42', ['cache-a', 'cache-b', 'cache-c']))

from hashlib import sha256

bits = bytearray(128)

def posicoes(valor):
    return [int.from_bytes(sha256(f'{i}:{valor}'.encode()).digest()[:4], 'big') % len(bits) for i in range(3)]

def adicionar(valor):
    for p in posicoes(valor):
        bits[p] = 1

def talvez_exista(valor):
    return all(bits[p] for p in posicoes(valor))

adicionar('pedido-42')
assert talvez_exista('pedido-42')

